create function pg_temp.bundle() returns jsonb language sql as $$select '
{"schema": "gina.curriculum-review.v1", "candidates": [{"key": "tr-2026-2027-t1-turkce2-g5-c6", "academic_year": "2026-2027", "term": 1, "exam": 1, "grade": 5, "subject": "Türkçe", "source_url": "https://cdn.eba.gov.tr/yardimcikaynaklar/2026/09/KSDT/turkce2.xlsx", "source_sha256": "6405d02aaaadaa4d25a3ce54954dd256a045da9f35d49ee806a3b29565a82cee", "sheet": "5. Sınıf", "header_cell": "C6", "question_count": 6, "blocks": [{"count": 2, "count_cell": "C12", "outcomes": [{"cell": "B12", "text": "T.O.5.6. Metnin yüzey anlamını belirleyebilme", "code": "T.O.5.6"}]}, {"count": 1, "count_cell": "C13", "outcomes": [{"cell": "B13", "text": "T.O.5.7. Görselle iletilen anlamı belirleyebilme", "code": "T.O.5.7"}]}, {"count": 1, "count_cell": "C21", "outcomes": [{"cell": "B21", "text": "T.O.5.20. Metinden hareketle söz varlığını geliştirmeye yönelik çözümleme yapabilme", "code": "T.O.5.20"}]}, {"count": 1, "count_cell": "C30", "outcomes": [{"cell": "B30", "text": "T.Y.5.13. Yazısını zenginleştirecek biçimde söz varlığını kullanabilme", "code": "T.Y.5.13"}]}, {"count": 1, "count_cell": "C32", "outcomes": [{"cell": "B32", "text": "T.Y.5.16. Yazım ve noktalama işaretleriyle ilgili kuralları uygulayabilme", "code": "T.Y.5.16"}]}], "label": "Senaryo 1", "review_reasons": ["programme_and_school_scope_required", "source_review_required"]}]}
'::jsonb$$;
create function pg_temp.review() returns jsonb language sql as $$select '{"programme":"Test programme version","school_scope":"Synthetic scope for testing only","programme_url":"https://tymm.meb.gov.tr/ogretim-programlari","source_checked":true,"counts_checked":true,"applicability_checked":true,"issues_resolution":"Synthetic evidence reviewed for test only.","note":"Test source review, not real catalogue approval."}'::jsonb$$;

insert into public.entitlement_overrides(family_id,plan,reason,ends_at) values('10000000-0000-4000-8000-000000005701','plus','Synthetic catalogue test',now()+interval '1 day');
insert into public.children(id,family_id,name,grade) values('20000000-0000-4000-8000-000000005702','10000000-0000-4000-8000-000000005701','Other sibling',5);
insert into public.prova_drafts(id,family_id,created_by,content) values('30000000-0000-4000-8000-000000005701','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701','{"childId":"20000000-0000-4000-8000-000000005701","grade":5,"subjects":["Türkçe"],"purpose":"written"}');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005702","role":"authenticated","gina":{"role":"parent","admin":true}}',true);
select public.admin_import_curriculum_candidates(gen_random_uuid(),pg_temp.bundle());
select set_config('test.id',public.admin_list_curriculum_candidates()->0->>'id',true);
select public.admin_change_curriculum_candidate(gen_random_uuid(),current_setting('test.id')::uuid,0,'review',pg_temp.review(),'Test review',true);
select public.admin_change_curriculum_candidate(gen_random_uuid(),current_setting('test.id')::uuid,1,'publish',null,'Test publication',true);
select set_config('test.body',jsonb_build_object('child_id','20000000-0000-4000-8000-000000005701','catalogue_id',current_setting('test.id'),'revision',2,'subject','Türkçe','confirmed',true)::text,true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005701","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000005701"}}',true);
select throws_ok($$select public.save_catalog_blueprint(gen_random_uuid(),current_setting('test.body')::jsonb)$$,'P0001','curriculum_unavailable','flag gates selection');
reset role;update public.app_settings set value='true' where key='curriculum_catalog.enabled';set local role authenticated;
select throws_ok($$select public.save_catalog_blueprint(gen_random_uuid(),current_setting('test.body')::jsonb||'{"confirmed":false}')$$,'P0001','curriculum_school_confirmation_required','school confirmation required');
select throws_ok($$select public.save_catalog_blueprint(gen_random_uuid(),current_setting('test.body')::jsonb||'{"subject":"Matematik"}')$$,'P0001','curriculum_scope_mismatch','wrong subject rejected');
select throws_ok($$select public.save_catalog_blueprint(gen_random_uuid(),current_setting('test.body')::jsonb||'{"revision":1}')$$,'P0001','curriculum_revision_conflict','old source revision rejected');
select throws_ok($$select public.save_catalog_blueprint(gen_random_uuid(),current_setting('test.body')::jsonb||jsonb_build_object('child_id',gen_random_uuid()))$$,'42501','forbidden','foreign child rejected');
select throws_ok($$select public.save_catalog_blueprint(gen_random_uuid(),current_setting('test.body')::jsonb||'{"officially_verified":true}')$$,'P0001',null,'cannot supply review provenance');
select set_config('test.bp',public.save_catalog_blueprint('60000000-0000-4000-8000-000000005701',current_setting('test.body')::jsonb)::text,true);
select is(public.save_catalog_blueprint('60000000-0000-4000-8000-000000005701',current_setting('test.body')::jsonb)::text,current_setting('test.bp'),'lost response exact replay');
select is(public.save_catalog_blueprint(gen_random_uuid(),current_setting('test.body')::jsonb)::text,current_setting('test.bp'),'new command same source version deduplicated');
select throws_ok($$select public.save_catalog_blueprint('60000000-0000-4000-8000-000000005701',current_setting('test.body')::jsonb||'{"revision":1}')$$,'P0001','request_conflict','cannot change intent');
select throws_ok($$select public.save_catalog_blueprint('60000000-0000-4000-8000-000000005701',null)$$,'P0001','request_conflict','null intent cannot replay');
select is((select count(*)::int from public.exam_blueprints),1,'one immutable family copy');
select is((select rows->0->>'topic' from public.exam_blueprints),'Blok 1','stable topic maps to full outputs');
select is((select (rows->0->>'count')::int from public.exam_blueprints),2,'combined source block count retained');
select throws_ok($$update public.exam_blueprints set rows='[]'$$,'P0001','curriculum_copy_immutable','parent cannot replace reviewed copy content');
select throws_ok($$update public.exam_blueprints set source_context='{}'$$,'P0001','curriculum_copy_immutable','parent cannot detach provenance');
select throws_ok($$select public.get_catalog_blueprint_context('10000000-0000-4000-8000-000000005701',current_setting('test.bp')::uuid)$$,'42501',null,'private binding resolver is server-only');
reset role;
select is((select snapshot->'candidate' from gina.catalog_blueprint_links),pg_temp.bundle()->'candidates'->0,'full original outcomes preserved without truncation');
select is((select snapshot->>'officially_verified' from gina.catalog_blueprint_links),'false','editorial review is not official endorsement');
select is((select count(*)::int from public.prova_generation_jobs),0,'selecting source never uses AI');
update public.children set grade=6 where id='20000000-0000-4000-8000-000000005701';
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.reserve_catalog_prova_generation('70000000-0000-4000-8000-000000005701','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701',repeat('a',64),6,current_setting('test.bp')::uuid,'30000000-0000-4000-8000-000000005701')$$,'P0001','curriculum_scope_mismatch','live child grade rechecked before charging');
reset role;update public.children set grade=5 where id='20000000-0000-4000-8000-000000005701';update public.prova_drafts set content=jsonb_set(content,'{childId}','"20000000-0000-4000-8000-000000005702"');set local role service_role;
select throws_ok($$select public.reserve_catalog_prova_generation('70000000-0000-4000-8000-000000005701','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701',repeat('a',64),6,current_setting('test.bp')::uuid,'30000000-0000-4000-8000-000000005701')$$,'P0001','curriculum_scope_mismatch','sibling scenario not silently substituted');
reset role;update public.prova_drafts set content=jsonb_set(content,'{childId}','"20000000-0000-4000-8000-000000005701"');update public.prova_drafts set content=jsonb_set(content,'{purpose}','"practice"');set local role service_role;
select throws_ok($$select public.reserve_catalog_prova_generation('70000000-0000-4000-8000-000000005701','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701',repeat('a',64),6,current_setting('test.bp')::uuid,'30000000-0000-4000-8000-000000005701')$$,'P0001','curriculum_scope_mismatch','written scope required');
reset role;update public.prova_drafts set content=jsonb_set(content,'{purpose}','"written"');set local role service_role;
select throws_ok($$select public.reserve_catalog_prova_generation('70000000-0000-4000-8000-000000005701','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701',repeat('a',64),5,current_setting('test.bp')::uuid,'30000000-0000-4000-8000-000000005701')$$,'P0001','curriculum_scope_mismatch','source total cannot be changed');
select ok(public.reserve_catalog_prova_generation('70000000-0000-4000-8000-000000005701','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701',repeat('a',64),6,current_setting('test.bp')::uuid,'30000000-0000-4000-8000-000000005701')?'lease','matching source/draft reserves once');
select is(public.reserve_catalog_prova_generation('70000000-0000-4000-8000-000000005701','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701',repeat('a',64),6,current_setting('test.bp')::uuid,'30000000-0000-4000-8000-000000005701')->>'error','generation_in_progress','parallel provider execution denied');
select is(public.reserve_catalog_prova_generation('70000000-0000-4000-8000-000000005701','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701',repeat('b',64),6,current_setting('test.bp')::uuid,'30000000-0000-4000-8000-000000005701')->>'error','request_conflict','replay still checks prompt identity');
select is(public.reserve_catalog_prova_generation('70000000-0000-4000-8000-000000005701','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701',repeat('a',64),6,current_setting('test.bp')::uuid,gen_random_uuid())->>'error','request_conflict','bound request cannot change draft');
reset role;select is((select count(*)::int from public.prova_generation_jobs),1,'only valid scope created a job');select is((select count(*)::int from gina.catalog_generation_links),1,'job has private source binding');
update gina.curriculum_candidates set status='withdrawn',revision=revision+1;set local role authenticated;select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005701","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000005701"}}',true);
select is(public.save_catalog_blueprint('60000000-0000-4000-8000-000000005701',current_setting('test.body')::jsonb)::text,current_setting('test.bp'),'withdrawal does not strand lost save response');select throws_ok($$select public.save_catalog_blueprint(gen_random_uuid(),current_setting('test.body')::jsonb)$$,'P0001','curriculum_unavailable','withdrawal blocks new selection');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.reserve_catalog_prova_generation('70000000-0000-4000-8000-000000005702','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701',repeat('a',64),6,current_setting('test.bp')::uuid,'30000000-0000-4000-8000-000000005701')->>'error','curriculum_unavailable','withdrawal blocks new provider charge');
select public.save_prova_provider_result('70000000-0000-4000-8000-000000005701',(select lease from public.prova_generation_jobs where id='70000000-0000-4000-8000-000000005701'),'{"output":{"questions":[]}}');
select ok(public.reserve_catalog_prova_generation('70000000-0000-4000-8000-000000005701','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701',repeat('a',64),6,current_setting('test.bp')::uuid,'30000000-0000-4000-8000-000000005701')?'provider_result','paid provider result can finish after withdrawal');
reset role;update public.prova_generation_jobs set status='done',result='{"questions":[]}' where id='70000000-0000-4000-8000-000000005701';set local role service_role;
select ok(public.reserve_catalog_prova_generation('70000000-0000-4000-8000-000000005701','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701',repeat('a',64),6,current_setting('test.bp')::uuid,'30000000-0000-4000-8000-000000005701')?'cached','completed result remains replayable after withdrawal');
reset role;update public.prova_generation_jobs set status='failed',provider_result=null where id='70000000-0000-4000-8000-000000005701';set local role service_role;
select is(public.reserve_catalog_prova_generation('70000000-0000-4000-8000-000000005701','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701',repeat('a',64),6,current_setting('test.bp')::uuid,'30000000-0000-4000-8000-000000005701')->>'error','curriculum_unavailable','failed retry cannot restart withdrawn provider work');
