update public.prova_generation_jobs set status='failed',provider_result=null;
-- Synthetic alias fixture: it tests matching, not an actual Fen source review.
insert into gina.curriculum_candidates(id,external_key,source_sha256,candidate,content_hash,status,revision,review,created_by)
select '80000000-0000-4000-8000-000000005701','synthetic-science-alias',repeat('b',64),jsonb_set(candidate,'{subject}','"Fen Bilimleri"'),repeat('b',64),'published',2,review,created_by from gina.curriculum_candidates limit 1;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005701","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000005701"}}',true);
select is(jsonb_array_length(public.get_curriculum_scenarios('20000000-0000-4000-8000-000000005701','2026-2027',1,1,'Fen')),1,'catalogue lookup accepts known subject alias');
select set_config('test.alias',public.save_catalog_blueprint(gen_random_uuid(),current_setting('test.body')::jsonb||'{"catalogue_id":"80000000-0000-4000-8000-000000005701","subject":"Fen"}')::text,true);
