reset role;update public.prova_drafts set content=jsonb_set(content,'{subjects}','["Fen"]');set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select ok(public.reserve_catalog_prova_generation('70000000-0000-4000-8000-000000005703','10000000-0000-4000-8000-000000005701','00000000-0000-4000-8000-000000005701',repeat('c',64),6,current_setting('test.alias')::uuid,'30000000-0000-4000-8000-000000005701')?'lease','known alias also works for bound generation');
reset role;
