select is((select count(*)::int from gina.catalog_blueprint_links),2,'creator deletion retains reviewed family content');
reset role;delete from public.children where id='20000000-0000-4000-8000-000000005701';select is((select count(*)::int from gina.catalog_blueprint_links),2,'deleted child does not downgrade copy to manual provenance');select ok((select bool_and(child_id is null) from gina.catalog_blueprint_links),'deleted child unlinked');select lives_ok($$delete from auth.users where id='00000000-0000-4000-8000-000000005701';set constraints all immediate;$$,'catalogue bindings do not block account deletion');select * from finish();rollback;
